// lib/core/console/commands/table_export_commands.dart

/// Table export, both builds (spec
/// docs/superpowers/specs/2026-11-28-table-export-design.md, amended: Excel
/// only): any CSV the console wrote, as BASA's export .xlsx with the
/// "Generated by" footer. Screens call TableExportViewModel with their own
/// rows instead.
library;

import 'dart:io';

import '../console_command.dart';
import '../console_registry.dart';
import '../file_output.dart';
import '../../../viewmodels/table_export_viewmodel.dart';

const _usage = 'Usage: export-table <in.csv> <out.xlsx> <title...> [school=<text>] [year=<text>] [filter=<text>]...';

void registerTableExportCommands(ConsoleRegistry registry, TableExportViewModel vm) {
  registry.register(ConsoleCommand(
    name: 'export-table',
    description: 'export-table <in.csv> <out.xlsx> <title...> [school=] [year=] [filter=]... — a CSV the console wrote, '
        'as an Excel table with the "Generated by" footer',
    handler: (args) async {
      try {
        if (args.length < 3 || args[2].contains('=')) return _usage;
        final input = args[0], output = args[1];
        if (!output.toLowerCase().endsWith('.xlsx')) return 'Use an output file ending in .xlsx.';
        final title = <String>[];
        String? school, year;
        final filters = <String>[];
        var options = false;
        for (final a in args.skip(2)) {
          final eq = a.indexOf('=');
          final key = eq < 0 ? null : a.substring(0, eq);
          if (key == 'school' || key == 'year' || key == 'filter') {
            options = true;
            final value = a.substring(eq + 1).trim();
            if (key == 'school') school = value;
            if (key == 'year') year = value;
            if (key == 'filter') filters.add(value);
          } else if (options && filters.isNotEmpty) {
            // An unquoted filter with spaces: "filter=Grade 7".
            filters[filters.length - 1] = '${filters.last} $a';
          } else if (options) {
            return _usage;
          } else {
            title.add(a);
          }
        }
        final String csv;
        try {
          csv = await File(input).readAsString();
        } on FileSystemException catch (e) {
          return "Couldn't read ${outputPath(input)}: ${e.osError?.message ?? e.message}";
        }
        final table = vm.tableFromCsv(csv, title.join(' '), school: school, schoolYear: year, filters: filters);
        final bytes = await vm.xlsx(table);
        return await writeOutputFile(output, bytes: bytes) ??
            'Wrote ${table.rows.length} row${table.rows.length == 1 ? '' : 's'} to ${outputPath(output)}';
      } catch (e) {
        return 'export-table failed: $e';
      }
    },
  ));
}
